effect.shader:
const int MAX_SAMPLES = 48;

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    int samples = clamp(int(quality + 0.5), 2, MAX_SAMPLES);

    vec2 toCenter = acScreenNorm - center;
    float rad = radians(angle);
    // Em pixels da COMPOSIÇÃO: `acEscalaDePixel` converte para o buffer, e a prévia
    // reduzida (o Auto da tela, o play) fica do tamanho da exportação (0.516.0).
    vec2 axis = vec2(cos(rad), sin(rad)) * acTexelSize * (strength * 700.0 * acEscalaDePixel);

    vec3 streak = vec3(0.0);
    float weightSum = 0.0;

    for (int i = 0; i < MAX_SAMPLES; i++) {
        if (i >= samples) break;
        // Vai dos dois lados a partir do pixel: o rastro se estende pra
        // frente e pra trás no caminho, como o Risco anamórfico já faz.
        float t = (float(i) / float(samples - 1)) * 2.0 - 1.0;

        vec2 uv;
        if (mode == 1) {
            // Giro: a amostra gira em torno do centro — mesma trajetória do
            // modo "Giro" de `radial-blur.xml`.
            float ang = strength * 1.5708 * t;
            float c = cos(ang);
            float s = sin(ang);
            uv = center + mat2(c, -s, s, c) * toCenter;
        } else if (mode == 2) {
            // Zoom: a amostra anda na direção do centro (ou se afasta, do
            // lado negativo de t) — mesma trajetória do modo "Zoom".
            uv = center + toCenter * (1.0 - strength * t);
        } else {
            // Linear: acumula ao longo de um eixo fixo.
            uv = acScreenNorm + axis * t;
        }

        vec4 texel = texture(inputImg, clamp(uv, 0.0, 1.0));
        float luma = dot(texel.rgb, vec3(0.299, 0.587, 0.114)) * texel.a;
        float bright = smoothstep(threshold, min(threshold + 0.2, 1.0), luma);

        // Peso caindo com a distância: sem isso o rastro tem a mesma força
        // na ponta e no meio, e parece uma barra em vez de um brilho.
        float weight = 1.0 - abs(t);
        streak += texel.rgb * bright * weight;
        weightSum += weight;
    }

    streak *= intensity / max(weightSum, 0.0001);

    // Somado: luz se acumula por cima. Misturar deixaria a imagem lavada
    // em vez de acesa.
    vec3 result = original.rgb + streak * streakColor.rgb * streakColor.a;
    fragColor = vec4(clamp(result, 0.0, 1.0), original.a);
}
